#include <stdio.h>

/* ===== 招牌区 =====
   在这块空地上挂两块招牌（两条宣告，行尾分号）：
   · fish_pack：收「每碗几条」和「几碗」，还总条数；
   · fish_left：收「整袋多少条」和「吃掉多少条」，还剩下的数。 */


int main(void) {
    int bag = fish_pack(2, 4);
    printf("码好 %d 条\n", bag);
    printf("还剩 %d 条\n", fish_left(bag, 3));
    return 0;
}

/* ===== 身子区 =====
   在这块空地上写两招的身子：
   · fish_pack：每碗 2 条、一共 4 碗，还总条数；
   · fish_left：整袋减掉吃掉的，还剩下的数。 */

items.referenceSolution:
#include <stdio.h>

/* ===== 招牌区 ===== */
int fish_pack(int per, int bowls);
int fish_left(int total, int eaten);

int main(void) {
    int bag = fish_pack(2, 4);
    printf("码好 %d 条\n", bag);
    printf("还剩 %d 条\n", fish_left(bag, 3));
    return 0;
}

/* ===== 身子区 ===== */
int fish_pack(int per, int bowls) {
    return per * bowls;
}

int fish_left(int total, int eaten) {
    return total - eaten;
}

